def find_minimal_edit(s_in, s_out):
    """Find the minimal change between two strings"""
    # Find first difference
    for i, (c1, c2) in enumerate(zip(s_in, s_out)):
        if c1 != c2:
            # Check if it's a simple substitution
            if len(s_in) == len(s_out):
                return (c1, c2, i)
            else:
                # This might be insertion/deletion
                # For now, let's focus on simple cases
                return (c1, c2, i)

    # If strings are identical, return None
    return None

inputs = ['uaxg', 'bk', 'evhahf', 'iveh', 'jagw']
outputs = ['ufxg', 'vgaguk', 'evhfhf', 'xveh', 'gfgw']

print("Analyzing minimal edits:")
for i, (inp, outp) in enumerate(zip(inputs, outputs)):
    edit = find_minimal_edit(inp, outp)
    print(f"Pair {i}: '{inp}' -> '{outp}' -> edit: {edit}")

