def find_all_changes(s_in, s_out):
    """Find all character-level changes between strings"""
    changes = []
    min_len = min(len(s_in), len(s_out))

    # Check character-by-character differences
    for i in range(min_len):
        if s_in[i] != s_out[i]:
            changes.append((i, s_in[i], s_out[i]))

    # Handle length differences
    if len(s_in) != len(s_out):
        if len(s_in) > len(s_out):
            # Deletion
            for i in range(min_len, len(s_in)):
                changes.append((i, s_in[i], None))
        else:
            # Insertion  
            for i in range(min_len, len(s_out)):
                changes.append((i, None, s_out[i]))

    return changes

inputs = ['uaxg', 'bk', 'evhahf', 'iveh', 'jagw']
outputs = ['ufxg', 'vgaguk', 'evhfhf', 'xveh', 'gfgw']

print("Detailed changes:")
for i, (inp, outp) in enumerate(zip(inputs, outputs)):
    changes = find_all_changes(inp, outp)
    print(f"{i}: '{inp}' -> '{outp}'")
    for change in changes:
        print(f"  Position {change[0]}: '{change[1]}' -> '{change[2]}'")

